package practice.day20261013;

import org.junit.jupiter.api.Test;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import static org.junit.jupiter.api.Assertions.*;

class Practice20261013Test {
    @Test void arithmeticEmptyAndSingle(){assertArrayEquals(new int[]{-1,0},ArithmeticRuns.longestArithmeticRun(new int[]{}));assertArrayEquals(new int[]{0,1},ArithmeticRuns.longestArithmeticRun(new int[]{4}));}
    @Test void arithmeticTwoElementsAlwaysLengthTwo(){assertArrayEquals(new int[]{0,2},ArithmeticRuns.longestArithmeticRun(new int[]{9,-9}));}
    @Test void arithmeticLongFirstRun(){assertArrayEquals(new int[]{0,4},ArithmeticRuns.longestArithmeticRun(new int[]{1,3,5,7,8,9}));}
    @Test void arithmeticLongestAtEnd(){assertArrayEquals(new int[]{3,4},ArithmeticRuns.longestArithmeticRun(new int[]{1,2,3,9,11,13,15}));}
    @Test void arithmeticEarliestTie(){assertArrayEquals(new int[]{0,3},ArithmeticRuns.longestArithmeticRun(new int[]{1,2,3,10,20,30}));}
    @Test void arithmeticZeroAndNegativeDifference(){assertArrayEquals(new int[]{0,4},ArithmeticRuns.longestArithmeticRun(new int[]{5,5,5,5}));assertArrayEquals(new int[]{1,4},ArithmeticRuns.longestArithmeticRun(new int[]{99,12,8,4,0}));}
    @Test void arithmeticIntOverflowBoundary(){assertArrayEquals(new int[]{0,2},ArithmeticRuns.longestArithmeticRun(new int[]{Integer.MIN_VALUE,Integer.MAX_VALUE,Integer.MIN_VALUE}));assertArrayEquals(new int[]{0,3},ArithmeticRuns.longestArithmeticRun(new int[]{Integer.MIN_VALUE,-1,Integer.MAX_VALUE-1}));}
    @Test void arithmeticInputNotModifiedAndNullRejected(){int[] input={4,2,0,8,9};int[] copy=input.clone();ArithmeticRuns.longestArithmeticRun(input);assertArrayEquals(copy,input);assertThrows(NullPointerException.class,()->ArithmeticRuns.longestArithmeticRun(null));}
    @Test void moveCommandValidAndInterfaceDispatch(){Command c=new MoveCommand("RIGHT",-2);assertEquals("RIGHT",c.label());assertEquals(-2,c.steps());Command wait=new WaitCommand();assertEquals("WAIT",wait.label());assertEquals(0,wait.steps());}
    @Test void moveCommandRejectsBlankLabel(){assertThrows(IllegalArgumentException.class,()->new MoveCommand(null,1));assertThrows(IllegalArgumentException.class,()->new MoveCommand("   ",1));assertEquals("X",new MoveCommand("X",0).label());}
    @Test void runnerEmptyCommandsOnlyCountsStart(){RunReport r=CommandRunner.execute(5,3,List.<Command>of());assertEquals(3,r.position());assertFalse(r.stopped());assertArrayEquals(new int[]{0,0,0,1,0},r.visitCounts());assertEquals(List.of(),r.executedLabels());}
    @Test void runnerRevisitsAccumulateWithInterfaceAndWait(){List<Command> cmds=List.of(new MoveCommand("R",2),new MoveCommand("L",-1),new WaitCommand(),new MoveCommand("R2",1),new MoveCommand("L2",-1));RunReport r=CommandRunner.execute(5,0,cmds);assertArrayEquals(new int[]{1,3,2,0,0},r.visitCounts());assertEquals(1,r.position());assertFalse(r.stopped());assertEquals(List.of("R","L","WAIT","R2","L2"),r.executedLabels());}
    @Test void runnerNonZeroStartNegativeMoves(){RunReport r=CommandRunner.execute(6,3,List.of(new MoveCommand("A",-2),new MoveCommand("B",1),new WaitCommand(),new MoveCommand("C",2)));assertEquals(4,r.position());assertArrayEquals(new int[]{0,1,2,2,1,0},r.visitCounts());}
    @Test void runnerZeroMoveRecordsLabelButNoVisits(){RunReport r=CommandRunner.execute(3,1,List.of(new WaitCommand(),new MoveCommand("Z",0)));assertEquals(1,r.position());assertArrayEquals(new int[]{0,1,0},r.visitCounts());assertEquals(List.of("WAIT","Z"),r.executedLabels());}
    @Test void runnerInvalidRightStopsAtomically(){RunReport r=CommandRunner.execute(4,0,List.of(new MoveCommand("A",1),new MoveCommand("BAD",5),new MoveCommand("L",-1)));assertEquals(1,r.position());assertTrue(r.stopped());assertArrayEquals(new int[]{1,1,0,0},r.visitCounts());assertEquals(List.of("A"),r.executedLabels());}
    @Test void runnerInvalidLeftStopsAtomically(){RunReport r=CommandRunner.execute(4,2,List.of(new MoveCommand("BAD",-3),new WaitCommand()));assertTrue(r.stopped());assertEquals(2,r.position());assertArrayEquals(new int[]{0,0,1,0},r.visitCounts());assertEquals(List.of(),r.executedLabels());}
    @Test void runnerOverflowAndMinValueMovesRejected(){RunReport high=CommandRunner.execute(4,2,List.of(new MoveCommand("H",Integer.MAX_VALUE)));RunReport low=CommandRunner.execute(4,2,List.of(new MoveCommand("L",Integer.MIN_VALUE)));assertTrue(high.stopped());assertTrue(low.stopped());assertArrayEquals(new int[]{0,0,1,0},high.visitCounts());assertArrayEquals(new int[]{0,0,1,0},low.visitCounts());}
    @Test void runnerDoesNotTouchCommandsAfterInvalid(){List<Command> input=new ArrayList<>();input.add(new MoveCommand("BAD",999));input.add(null);RunReport r=CommandRunner.execute(2,0,input);assertTrue(r.stopped());assertEquals(List.of(),r.executedLabels());}
    @Test void runnerNullCommandBeforeInvalidRejected(){List<Command> input=new ArrayList<>();input.add(null);assertThrows(NullPointerException.class,()->CommandRunner.execute(2,0,input));}
    @Test void runnerValidatesSizeStartAndList(){assertThrows(IllegalArgumentException.class,()->CommandRunner.execute(0,0,List.of()));assertThrows(IllegalArgumentException.class,()->CommandRunner.execute(3,-1,List.of()));assertThrows(IllegalArgumentException.class,()->CommandRunner.execute(3,3,List.of()));assertThrows(NullPointerException.class,()->CommandRunner.execute(3,0,null));}
    @Test void sortingByMagnitudeThenLabelWithoutMutation(){MoveCommand big=new MoveCommand("BIG",9),b=new MoveCommand("B",-1),a=new MoveCommand("A",1),z=new MoveCommand("Z",0);List<MoveCommand> source=new ArrayList<>(List.of(big,b,a,z));List<MoveCommand> sorted=CommandRunner.sortedCopyByMagnitude(source);assertEquals(List.of(z,a,b,big),sorted);assertEquals(List.of(big,b,a,z),source);assertNotSame(source,sorted);}
    @Test void sortingMinValueMustUseLongAbs(){MoveCommand min=new MoveCommand("MIN",Integer.MIN_VALUE),max=new MoveCommand("MAX",Integer.MAX_VALUE),zero=new MoveCommand("ZERO",0);assertEquals(List.of(zero,max,min),CommandRunner.sortedCopyByMagnitude(List.of(min,zero,max)));}
    @Test void sortingWorksWithInterfaceAndEmptyList(){List<Command> cmds=List.of(new WaitCommand(),new MoveCommand("A",2));assertEquals(List.of(cmds.get(0),cmds.get(1)),CommandRunner.sortedCopyByMagnitude(cmds));assertEquals(List.of(),CommandRunner.sortedCopyByMagnitude(List.<Command>of()));}
    @Test void sortingRejectsNullListAndElement(){assertThrows(NullPointerException.class,()->CommandRunner.sortedCopyByMagnitude(null));assertThrows(NullPointerException.class,()->CommandRunner.sortedCopyByMagnitude(Arrays.asList(new WaitCommand(),null)));}
    @Test void reportDefensiveCopyAtConstruction(){int[] counts={1,2};List<String> labels=new ArrayList<>(List.of("X"));RunReport report=new RunReport(1,false,counts,labels);counts[1]=99;labels.add("Y");assertArrayEquals(new int[]{1,2},report.visitCounts());assertEquals(List.of("X"),report.executedLabels());}
    @Test void reportDefensiveGetterAndImmutableLabels(){RunReport report=new RunReport(0,false,new int[]{1},List.of("A"));int[] leaked=report.visitCounts();leaked[0]=100;assertArrayEquals(new int[]{1},report.visitCounts());assertNotSame(leaked,report.visitCounts());assertThrows(UnsupportedOperationException.class,()->report.executedLabels().add("B"));}
    @Test void reportRejectsNullData(){assertThrows(NullPointerException.class,()->new RunReport(0,false,null,List.of()));assertThrows(NullPointerException.class,()->new RunReport(0,false,new int[1],null));}
}
